#include <torch/extension.h>
#include <hip/hip_runtime.h>

using namespace torch;

__global__ void channel_softmax_kernel(
    const float* input,
    float* output,
    int N, int C, int D, int H, int W) {

    int n = blockIdx.x;
    int d = blockIdx.y;
    int hW = blockIdx.z;
    int h = hW / W;
    int w = hW % W;

    if (n >= N || d >= D || h >= H || w >= W) return;

    int c = threadIdx.x;
    if (c >= C) return;

    const int idx_offset = n * C * D * H * W + d * H * W + h * W + w;

    __shared__ float smax[16];
    __shared__ float sexp[16];

    float val = input[c * D * H * W + idx_offset];
    smax[c] = val;
    __syncthreads();

    for (int stride = C/2; stride > 0; stride >>= 1) {
        if (c < stride) smax[c] = fmaxf(smax[c], smax[c + stride]);
        __syncthreads();
    }

    float max_val = smax[0];
    float exp_val = expf(val - max_val);
    sexp[c] = exp_val;
    __syncthreads();

    for (int stride = C/2; stride > 0; stride >>= 1) {
        if (c < stride) sexp[c] += sexp[c + stride];
        __syncthreads();
    }

    output[c * D * H * W + idx_offset] = exp_val / sexp[0];
}

Tensor channel_softmax_rocm(Tensor input) {
    TORCH_CHECK(input.is_contiguous() && input.dim() == 5, "Invalid input");
    int N = input.size(0), C = input.size(1), D = input.size(2), H = input.size(3), W = input.size(4);
    Tensor output = torch::empty_like(input);
    dim3 grid(N, D, H * W), block(C);
    hipLaunchKernelGGL(channel_softmax_kernel, grid, block, 0, 0,
        input.data_ptr<float>(), output.data_ptr<float>(), N, C, D, H, W);
    hipStreamSynchronize(0);
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_sub_tanh_kernel(const float* input, const float* bias, float* output, int batch_size, int out_channels, int height, int width) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * height * width;
    if (index < total_elements) {
        int n = index / (out_channels * height * width);
        int c = (index % (out_channels * height * width)) / (height * width);
        float bias_val = bias[c];
        output[index] = tanhf(input[index] - bias_val);
    }
}

torch::Tensor fused_sub_tanh_rocm(torch::Tensor input, torch::Tensor bias) {
    auto output = torch::zeros_like(input);
    int total_elements = input.numel();
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_sub_tanh_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), 
        input.size(0), input.size(1), input.size(2), input.size(3));

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_kernel(const float* input, float* output, int rows, int cols) {
    int row_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (row_idx >= rows) return;

    const float* row_start = input + row_idx * cols;
    float max_val = -INFINITY;

    // Compute max across columns for this row
    for (int i = 0; i < cols; ++i) {
        if (row_start[i] > max_val) {
            max_val = row_start[i];
        }
    }

    // Compute GELU(0) fusion (since subtraction is always zero)
    output[row_idx] = 0.0f;
}

torch::Tensor custom_operation(torch::Tensor input) {
    int rows = input.size(0);
    auto output = torch::zeros({rows, 1}, input.options());

    const int block_size = 256;
    int num_blocks = (rows + block_size - 1) / block_size;

    fused_kernel<<<num_blocks, block_size, 0, at::hip::getCurrentHIPStream()>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        input.size(1)
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_op_kernel(const float* input, const float* scaling_factor, const float* bias, float* output, int channels, int depth, int height, int width, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int product_DHW = depth * height * width;
    int c = (idx / product_DHW) % channels;

    float val = input[idx];
    val *= scaling_factor[c];
    val = tanhf(val);
    val *= bias[c];
    val = 1.0f / (1.0f + expf(-val));

    output[idx] = val;
}

torch::Tensor fused_op_rocm(torch::Tensor input, torch::Tensor scaling_factor, torch::Tensor bias) {
    auto output = torch::zeros_like(input);
    int total_elements = input.numel();

    auto sizes = input.sizes();
    int channels = sizes[1];
    int depth = sizes[2];
    int height = sizes[3];
    int width = sizes[4];

    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_op_kernel,
        dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        scaling_factor.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        channels,
        depth,
        height,
        width,
        total_elements
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_ops_kernel(const float* linear_out, float subtract_val, float multiply_val, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = linear_out[idx];
        val = (val - subtract_val) * multiply_val;
        out[idx] = fmaxf(val, 0.0f);
    }
}

torch::Tensor fused_ops_rocm(torch::Tensor linear_out, float subtract_val, float multiply_val) {
    auto out = torch::empty_like(linear_out);
    int size = linear_out.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        linear_out.data_ptr<float>(), subtract_val, multiply_val, 
        out.data_ptr<float>(), size
    );

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

#define CHECK_HIP(x) TORCH_CHECK(x.is_cuda(), #x " must be a HIP tensor")
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")

__global__ void bn_tanh_kernel(
    const float* input, float* output, 
    const float* gamma, const float* beta,
    const float* mean, const float* var,
    int C, int H, int W, int numel, float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) return;

    int n = idx / (C * H * W);
    int c = (idx / (H * W)) % C;

    float inv_std = rsqrtf(var[c] + eps);
    float val = (input[idx] - mean[c]) * gamma[c] * inv_std + beta[c];
    output[idx] = tanhf(val);
}

torch::Tensor bn_tanh_rocm(
    torch::Tensor input, 
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor mean,
    torch::Tensor var,
    float eps) {

    CHECK_HIP(input); CHECK_CONTIGUOUS(input);
    CHECK_HIP(gamma); CHECK_CONTIGUOUS(gamma);
    CHECK_HIP(beta); CHECK_CONTIGUOUS(beta);
    CHECK_HIP(mean); CHECK_CONTIGUOUS(mean);
    CHECK_HIP(var); CHECK_CONTIGUOUS(var);

    auto output = torch::empty_like(input);
    int numel = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    dim3 block(256);
    dim3 grid((numel + block.x - 1) / block.x);

    hipLaunchKernelGGL(bn_tanh_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        mean.data_ptr<float>(), var.data_ptr<float>(),
        C, H, W, numel, eps);

    return output;
}

