__global__ void double_mish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float sp = log1p(exp(x));
        float m1 = x * tanh(sp);
        sp = log1p(exp(m1));
        output[idx] = m1 * tanh(sp);
    }
}

torch::Tensor double_mish_rocm(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    dim3 grid((size + block_size - 1) / block_size);
    hipStream_t stream = at::hip::getCurrentHIPStream().stream();
    double_mish_kernel<<<grid, block_size, 0, stream>>>(
        x.data_ptr<float>(), output.data_ptr<float>(), size
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_sigmoid_scale_add_kernel(const float* input, float* output, int size, float scaling_factor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        float sig = 1.0f / (1.0f + expf(-val));
        output[idx] = val + sig * scaling_factor;
    }
}

torch::Tensor fused_sigmoid_scale_add_rocm(torch::Tensor input, float scaling_factor) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    auto stream = at::cuda::getCurrentHIPStream();
    fused_sigmoid_scale_add_kernel<<<num_blocks, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size,
        scaling_factor
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

#define HIP_CHECK(err) { hipError_t err_ = (err); if (err_ != hipSuccess) { throw std::runtime_error(hipGetErrorString(err_)); } }

__global__ void fused_gemm_bias_relu_kernel(
    const float* input, const float* weight, const float* bias,
    float* output, int M, int N, int K,
    int input_row_stride, int input_col_stride,
    int weight_row_stride, int weight_col_stride) {

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for(int k = 0; k < K; k++) {
            sum += input[row * input_row_stride + k * input_col_stride] 
                 * weight[col * weight_row_stride + k * weight_col_stride];
        }
        sum += bias[col];
        output[row * N + col] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor fused_gemm_bias_relu_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int M, int N, int K) {
    auto output = torch::empty({M, N}, input.options());
    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    int input_row_stride = input.stride(0);
    int input_col_stride = input.stride(1);
    int weight_row_stride = weight.stride(0);
    int weight_col_stride = weight.stride(1);

    hipLaunchKernelGGL(fused_gemm_bias_relu_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        output.data_ptr<float>(), M, N, K,
        input_row_stride, input_col_stride,
        weight_row_stride, weight_col_stride
    );

    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    return output;
}

