__global__ void fused_multiply_lrelu_kernel(const float* input, float* output, float multiplier, float negative_slope, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] * multiplier;
        output[idx] = (val > 0) ? val : val * negative_slope;
    }
}

torch::Tensor fused_multiply_lrelu_rocm(torch::Tensor input, float multiplier, float negative_slope) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_multiply_lrelu_kernel, 
        dim3(num_blocks), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        multiplier, 
        negative_slope, 
        size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cmath>

__global__ void fused_act_kernel(const float* x, const float* add_vec, float* out, int out_features, int total) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int j = idx % out_features;
    float v = x[idx] + add_vec[j];

    // Swish
    v *= 1.0f / (1.0f + expf(-v));

    // Tanh
    v = tanhf(v);

    // GELU approx
    v = 0.5f * v * (1.0f + tanhf(0.7978845608028654f * (v + 0.044715f * v*v*v)));

    // Hardtanh
    out[idx] = fminf(fmaxf(v, -1.0f), 1.0f);
}

torch::Tensor fused_activation_rocm(torch::Tensor x, torch::Tensor add_vec) {
    TORCH_CHECK(x.is_cuda() && add_vec.is_cuda(), "Tensors must be on GPU");
    TORCH_CHECK(x.is_contiguous() && add_vec.is_contiguous(), "Requires contiguous tensors");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(add_vec.dim() == 1, "add_vec must be 1D");
    TORCH_CHECK(x.size(1) == add_vec.size(0), "Dimension mismatch");

    auto out = torch::empty_like(x);
    int total = x.numel();
    int out_feat = x.size(1);

    int block = 256;
    int grid = (total + block - 1) / block;

    hipStream_t stream = at::hip::getCurrentHIPStream().stream();
    fused_act_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(), add_vec.data_ptr<float>(), 
        out.data_ptr<float>(), out_feat, total
    );

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void maxpool_hardtanh_kernel(const float* input, float* output, int B, int C, int H, int W, int kH, int kW, int sH, int sW, float min_val, float max_val, int oH, int oW) {
    int b = blockIdx.z;
    int c = blockIdx.y;
    int h_out = blockIdx.x;
    int w_out = threadIdx.x;

    if (b >= B || c >= C || h_out >= oH || w_out >= oW) return;

    int start_h = h_out * sH;
    int start_w = w_out * sW;
    int end_h = min(start_h + kH, H);
    int end_w = min(start_w + kW, W);

    float max_val_region = -__FLT_MAX__;
    for (int h = start_h; h < end_h; ++h) {
        for (int w = start_w; w < end_w; ++w) {
            float val = input[b*C*H*W + c*H*W + h*W + w];
            if (val > max_val_region) max_val_region = val;
        }
    }

    max_val_region = fminf(max_val, fmaxf(min_val, max_val_region));
    output[b*C*oH*oW + c*oH*oW + h_out*oW + w_out] = max_val_region;
}

torch::Tensor maxpool_hardtanh_rocm(torch::Tensor x, int k, int s, float min_val, float max_val) {
    int B = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
    int oH = (H - k)/s + 1;
    int oW = (W - k)/s + 1;
    auto output = torch::zeros({B, C, oH, oW}, x.options());

    dim3 blocks(oH, C, B);
    hipLaunchKernelGGL(maxpool_hardtanh_kernel, blocks, oW, 0, at::cuda::getCurrentHIPStream(), 
        x.data_ptr<float>(), output.data_ptr<float>(), B, C, H, W, k, k, s, s, min_val, max_val, oH, oW);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define __shfl_down(var, delta) __shfl_down(var, delta, 64)

template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);
    return val;
}

template<typename T>
__inline__ __device__ T warpReduceMax(T val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val = max(val, __shfl_down(val, offset));
    return val;
}

__global__ void fused_kernel(const float* input, const float* bias,
                             float* output, int B, int C, int D, int H, int W) {
    int b = blockIdx.z;
    int d = blockIdx.y;
    int hw = blockIdx.x;
    int h = hw / W;
    int w = hw % W;
    int c = threadIdx.x;

    if (b >= B || d >= D || h >= H || w >= W || c >= C) return;

    // Calculate input index
    int input_idx = b * C * D * H * W 
                  + c * D * H * W 
                  + d * H * W 
                  + h * W 
                  + w;

    float x = input[input_idx];
    float exp_x = expf(x);

    __shared__ float log_sum_exp;

    // Block-wide sum of exponentials
    float sum_exp = warpReduceSum(exp_x);
    sum_exp += __shfl_down(sum_exp, 16); // For 32 threads/warp, adjust for 16

    if (c == 0) {
        log_sum_exp = logf(sum_exp);
    }
    __syncthreads();

    // Compute v = log_sum_exp * sigmoid(log_sum_exp + 3) /6
    float v = log_sum_exp * (1.0f / (1.0f + expf(-(log_sum_exp + 3.0f)))) / 6.0f;

    // Compute clamped values and find max
    float bias_val = bias[c];
    float u = v - bias_val;
    u = fminf(fmaxf(u, -1.0f), 1.0f);

    // Block-wide max
    float max_u = warpReduceMax(u);
    max_u = max(max_u, __shfl_down(max_u, 16)); // Adjust for 16 channels

    if (c == 0) {
        int output_idx = b * 1 * D * H * W
                       + d * H * W 
                       + h * W 
                       + w;
        output[output_idx] = max_u;
    }
}

torch::Tensor fused_op_rocm(torch::Tensor input, torch::Tensor bias) {
    int B = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto output = torch::zeros({B, 1, D, H, W}, input.options());

    dim3 blocks(H*W, D, B);
    int channels = C;

    hipLaunchKernelGGL(fused_kernel, 
        dim3(blocks), dim3(channels), 0, at::cuda::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        output.data_ptr<float>(), 
        B, C, D, H, W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void clamp_mult_max_kernel(
    const float* input, const float* multiplier, float* output,
    float clamp_min, float clamp_max,
    int batch_size, int channels, int depth, int height, int width) {

    int total_spatial = depth * height * width;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = gridDim.x * blockDim.x;

    __shared__ float smem_multiplier[16];
    if (threadIdx.x < channels) smem_multiplier[threadIdx.x] = multiplier[threadIdx.x];
    __syncthreads();

    for (int i = idx; i < batch_size * total_spatial; i += total_threads) {
        int b = i / total_spatial;
        int spatial = i % total_spatial;
        int d = spatial / (height * width);
        int h = (spatial % (height * width)) / width;
        int w = spatial % width;

        float max_val = -INFINITY;
        for (int c = 0; c < channels; ++c) {
            int input_idx = b * channels * depth * height * width 
                          + c * depth * height * width 
                          + d * height * width 
                          + h * width 
                          + w;
            float val = input[input_idx];
            val = fmaxf(clamp_min, fminf(clamp_max, val));
            val *= smem_multiplier[c];
            if (val > max_val) max_val = val;
        }
        output[b * total_spatial + spatial] = max_val;
    }
}

torch::Tensor clamp_mult_max_rocm(torch::Tensor input, torch::Tensor multiplier, 
                                float clamp_min, float clamp_max) {
    TORCH_CHECK(input.dim() == 5, "input must be 5D");
    TORCH_CHECK(multiplier.dim() == 1, "multiplier must be 1D");
    int batch_size = input.size(0);
    int channels = input.size(1);
    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    auto output = torch::empty({batch_size, depth, height, width}, input.options());
    int total = batch_size * depth * height * width;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    hipLaunchKernelGGL(clamp_mult_max_kernel,
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(), multiplier.data_ptr<float>(), output.data_ptr<float>(),
        clamp_min, clamp_max,
        batch_size, channels, depth, height, width
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void elementwise_fused_kernel(const float* input, const float* multiplier, float* output, int num_elements, int channels, int height, int width, float negative_slope) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= num_elements) return;

    int total_per_batch = channels * height * width;
    int n = idx / total_per_batch;
    int remaining = idx % total_per_batch;
    int c = remaining / (height * width);

    float x = input[idx];
    float mval = multiplier[c];

    x *= mval;

    x = fmaxf(x, negative_slope * x);

    const float sqrt_2_over_pi = sqrtf(2.0f / 3.14159265358979323846f);
    float x_cubed = x * x * x;
    float tanh_arg = sqrt_2_over_pi * (x + 0.044715f * x_cubed);
    float gelu = 0.5f * x * (1.0f + tanhf(tanh_arg));

    output[idx] = gelu;
}

torch::Tensor elementwise_fused_rocm(torch::Tensor input, torch::Tensor multiplier, float negative_slope) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int channels = multiplier.size(0);
    int height = input.size(2);
    int width = input.size(3);

    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    hipLaunchKernelGGL(elementwise_fused_kernel, grid, block_size, 0, 0, 
        input.data_ptr<float>(), multiplier.data_ptr<float>(), output.data_ptr<float>(),
        num_elements, channels, height, width, negative_slope);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__global__ void logsumexp_relu_kernel(const float* input, float* output, int batch_size, int channels,
                                     int depth, int height, int width) {
    int num_spatial = depth * height * width;
    int total_elements = batch_size * num_spatial;

    for (int linear_idx = blockIdx.x * blockDim.x + threadIdx.x;
         linear_idx < total_elements;
         linear_idx += blockDim.x * gridDim.x) {
        int b = linear_idx / num_spatial;
        int spatial_idx = linear_idx % num_spatial;
        int d = spatial_idx / (height * width);
        int remaining = spatial_idx % (height * width);
        int h = remaining / width;
        int w = remaining % width;

        float max_val = -FLT_MAX;
        for (int c = 0; c < channels; ++c) {
            int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
            max_val = fmaxf(max_val, input[input_idx]);
        }

        float sum_exp = 0.0f;
        for (int c = 0; c < channels; ++c) {
            int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
            sum_exp += expf(input[input_idx] - max_val);
        }

        float result = max_val + logf(sum_exp);
        result = fmaxf(result, 0.0f);

        int output_idx = (b * depth * height * width) + (d * height * width) + (h * width) + w;
        output[output_idx] = result;
    }
}

torch::Tensor logsumexp_relu_rocm(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto depth = input.size(2);
    auto height = input.size(3);
    auto width = input.size(4);

    auto output = torch::zeros({batch_size, 1, depth, height, width}, input.options());

    int total_elements = batch_size * depth * height * width;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(logsumexp_relu_kernel,
        dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels, depth, height, width
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_bias_hardtanh_mish_kernel(
    const float* input,
    const float* bias,
    float* output,
    int num_elements,
    int feature_size,
    float min_val,
    float max_val) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int bias_idx = idx % feature_size;
        float val = input[idx] + bias[bias_idx];
        val = fmaxf(min_val, fminf(max_val, val));
        float softplus_val = log1pf(expf(val));
        output[idx] = val * tanhf(softplus_val);
    }
}

torch::Tensor fused_bias_hardtanh_mish_rocm(
    torch::Tensor input,
    torch::Tensor bias,
    int feature_size,
    float min_val,
    float max_val) {

    auto num_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bias_hardtanh_mish_kernel, 
        dim3(grid_size), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        feature_size,
        min_val,
        max_val
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_ops_kernel(const float* input, const float* bias, float* output, 
                               int num_elements, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int elements_per_channel = D * H * W;
        int ch = (idx % (C * elements_per_channel)) / elements_per_channel;

        float val = input[idx];
        val = fmaxf(0.0f, val);  // ReLU
        val = fmaxf(0.01f * val, val);  // LeakyReLU
        val *= 0.5f * (1.0f + tanhf(0.7978845608028654f * (val + 0.044715f * val*val*val)));  // GELU
        val = 1.0f / (1.0f + expf(-val));  // Sigmoid
        output[idx] = val + bias[ch];
    }
}

torch::Tensor fused_ops_rocm(torch::Tensor input, torch::Tensor bias) {
    int num_elements = input.numel();
    auto output = torch::empty_like(input);

    auto sizes = input.sizes();
    int C = sizes[1], D = sizes[2], H = sizes[3], W = sizes[4];

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_ops_kernel,
        dim3(grid_size), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        C, D, H, W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_matmul_scale_add_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    float scaling_factor,
    int batch_size,
    int in_feats,
    int out_feats
) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    const int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < batch_size && col < out_feats) {
        float sum = bias[col];
        for (int i = 0; i < in_feats; ++i) {
            sum += input[row * in_feats + i] * weight[col * in_feats + i];
        }
        output[row * out_feats + col] = sum * (1.0f + scaling_factor);
    }
}

torch::Tensor fused_matmul_scale_add_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float scaling_factor
) {
    const int batch_size = input.size(0);
    const int in_feats = input.size(1);
    const int out_feats = weight.size(0);

    auto output = torch::zeros({batch_size, out_feats}, input.options());

    const int TILE = 16;
    dim3 blocks(
        (batch_size + TILE - 1) / TILE,
        (out_feats + TILE - 1) / TILE
    );
    dim3 threads(TILE, TILE);

    hipLaunchKernelGGL(fused_matmul_scale_add_kernel,
        blocks, threads, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        batch_size,
        in_feats,
        out_feats
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_avg_pool_kernel(
    const float* input,
    float* output,
    int D_out,
    int H_out,
    int W_out,
    int D_in,
    int H_in,
    int W_in,
    int batch_size,
    int channels
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_out_elements = batch_size * channels * D_out * H_out * W_out;
    if (idx >= total_out_elements) return;

    int b = idx / (channels * D_out * H_out * W_out);
    int rem = idx % (channels * D_out * H_out * W_out);
    int c = rem / (D_out * H_out * W_out);
    rem = rem % (D_out * H_out * W_out);
    int d_out = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    int d_start = d_out * 4;
    int d_end = d_start + 4;
    int h_start = h_out * 4;
    int h_end = h_start + 4;
    int w_start = w_out * 4;
    int w_end = w_start + 4;

    d_end = min(d_end, D_in);
    h_end = min(h_end, H_in);
    w_end = min(w_end, W_in);

    float sum = 0.0f;
    int count = 0;
    for (int d = d_start; d < d_end; ++d) {
        for (int h = h_start; h < h_end; ++h) {
            for (int w = w_start; w < w_end; ++w) {
                int input_idx = b * channels * D_in * H_in * W_in +
                                c * D_in * H_in * W_in +
                                d * H_in * W_in +
                                h * W_in +
                                w;
                sum += input[input_idx];
                count++;
            }
        }
    }

    output[idx] = count > 0 ? sum / count : 0.0f;
}

torch::Tensor fused_avg_pool_rocm(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto D_in = input.size(2);
    auto H_in = input.size(3);
    auto W_in = input.size(4);

    int D_out = D_in / 4;
    int H_out = H_in / 4;
    int W_out = W_in / 4;

    auto output = torch::zeros({batch_size, channels, D_out, H_out, W_out}, input.options());

    int total_elements = batch_size * channels * D_out * H_out * W_out;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_avg_pool_kernel,
        num_blocks, block_size, 0, 0,
        input.data_ptr<float>(), output.data_ptr<float>(),
        D_out, H_out, W_out, D_in, H_in, W_in,
        batch_size, channels
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void mean_subtract_kernel(const float* input, float* output, int B, int C, int D, int H, int W) {
    extern __shared__ float shared_sum[];
    int bc = blockIdx.x;
    int b = bc / C;
    int c = bc % C;

    int spatial_size = D * H * W;
    int tid = threadIdx.x;

    float sum = 0.0f;

    for (int i = tid; i < spatial_size; i += blockDim.x) {
        int d = i / (H * W);
        int h = (i % (H * W)) / W;
        int w = i % W;
        int idx = ((b * C + c) * D + d) * H * W + h * W + w;
        sum += input[idx];
    }

    shared_sum[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = shared_sum[0] / (float) spatial_size;
        shared_sum[0] = mean;
    }
    __syncthreads();

    float mean_val = shared_sum[0];

    for (int i = tid; i < spatial_size; i += blockDim.x) {
        int d = i / (H * W);
        int h = (i % (H * W)) / W;
        int w = i % W;
        int idx = ((b * C + c) * D + d) * H * W + h * W + w;
        output[idx] = input[idx] - mean_val;
    }
}

torch::Tensor mean_subtract_rocm(torch::Tensor x) {
    auto B = x.sizes()[0];
    auto C = x.sizes()[1];
    auto D = x.sizes()[2];
    auto H = x.sizes()[3];
    auto W = x.sizes()[4];

    torch::Tensor x_contig = x.contiguous();
    torch::Tensor output = torch::empty_like(x_contig);

    int num_blocks = B * C;
    int block_size = 256;

    size_t shared_mem = block_size * sizeof(float);

    hipStream_t stream = at::cuda::getCurrentHIPStream();

    mean_subtract_kernel<<<num_blocks, block_size, shared_mem, stream>>>(
        x_contig.data_ptr<float>(),
        output.data_ptr<float>(),
        B,
        C,
        D,
        H,
        W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>
#include <math.h>

#define BLOCK_SIZE 256

__device__ __inline__ float gelu_activation(float x) {
    return 0.5f * x * (1.0f + erff(x * 0.7071067811865475f));
}

__global__ void fused_gelu_group_norm_kernel(
    const float* input, float* output,
    const float* gamma, const float* beta,
    int B, int C, int H, int W,
    int G, float eps) {

    extern __shared__ float smem[];
    int batch = blockIdx.y;
    int group = blockIdx.x;
    int ch_per_group = C / G;
    int spatial_size = H * W;

    int tid = threadIdx.x;
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = tid; i < ch_per_group * spatial_size; i += blockDim.x) {
        int c = i / spatial_size;
        int s = i % spatial_size;
        int idx = batch * C * spatial_size + (group * ch_per_group + c) * spatial_size + s;
        float val = input[idx];
        float gelu_val = gelu_activation(val);
        sum += gelu_val;
        sum_sq += gelu_val * gelu_val;
    }

    smem[tid] = sum;
    smem[tid + blockDim.x] = sum_sq;
    __syncthreads();

    for (int offset = blockDim.x/2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            smem[tid] += smem[tid + offset];
            smem[tid + blockDim.x] += smem[tid + offset + blockDim.x];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = smem[0] / (ch_per_group * spatial_size);
        float var = (smem[blockDim.x] / (ch_per_group * spatial_size)) - mean * mean;
        float inv_std = rsqrtf(var + eps);

        for (int i = 0; i < ch_per_group * spatial_size; ++i) {
            int c = i / spatial_size;
            int s = i % spatial_size;
            int idx = batch * C * spatial_size + (group * ch_per_group + c) * spatial_size + s;
            float val = input[idx];
            float gelu_val = gelu_activation(val);
            output[idx] = (gelu_val - mean) * inv_std * gamma[group * ch_per_group + c] + beta[group * ch_per_group + c];
        }
    }
}

torch::Tensor fused_gelu_group_norm_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    auto output = torch::empty_like(input);
    dim3 grid(num_groups, B);
    size_t shared_mem = 2 * BLOCK_SIZE * sizeof(float);

    hipLaunchKernelGGL(fused_gelu_group_norm_kernel, 
        grid, BLOCK_SIZE, shared_mem, 
        c10::hip::getCurrentHIPStream(),
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        B, C, H, W, num_groups, eps
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_matmul_avgpool_kernel(const float* x, const float* weight, const float* bias, float* output, int batch_size, int in_features, int out_features, int pool_size) {
    const int pooled_out = out_features / pool_size;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int b = idx / pooled_out;
    const int j = idx % pooled_out;

    if (b >= batch_size || j >= pooled_out) return;

    float sum_val = 0.0f;

    for (int k = 0; k < pool_size; ++k) {
        const int row = j * pool_size + k;
        if (row >= out_features) break;

        float dot = 0.0f;
        for (int d = 0; d < in_features; ++d) {
            dot += x[b * in_features + d] * weight[row * in_features + d];
        }
        dot += bias[row];
        sum_val += dot;
    }

    sum_val /= pool_size;

    output[b * pooled_out + j] = sum_val;
}

torch::Tensor fused_matmul_avgpool_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, int pool_size) {
    TORCH_CHECK(x.dim() == 2, "Expected x to be 2-dimensional");
    const int batch_size = x.size(0);
    const int in_features = x.size(1);
    const int out_features = weight.size(0);
    const int pooled_out = out_features / pool_size;

    auto output = torch::zeros({batch_size, pooled_out}, x.options());

    const int total_threads = batch_size * pooled_out;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_matmul_avgpool_kernel,
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, in_features, out_features, pool_size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_hardswish_relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float shifted = x + 3.0f;
        float clamped = fmaxf(0.0f, fminf(shifted, 6.0f));
        float hardswish_val = x * clamped / 6.0f;
        output[idx] = fmaxf(hardswish_val, 0.0f);
    }
}

torch::Tensor fused_hardswish_relu_rocm(torch::Tensor x) {
    auto output = torch::zeros_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    fused_hardswish_relu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_kernel(const float* x, const float* weight, float* output, 
                             int batch_size, int input_size, int hidden_size, 
                             float scaling_factor) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (batch_idx >= batch_size)
        return;

    const float* x_i = x + batch_idx * input_size;
    float sum = 0.0f;

    for (int j = 0; j < hidden_size; ++j) {
        const float* w_j = weight + j * input_size;
        float dot = 0.0f;

        for (int k = 0; k < input_size; ++k) {
            dot += x_i[k] * w_j[k];
        }

        sum += dot;
    }

    sum = sum * (0.5f * scaling_factor);
    output[batch_idx] = sum;
}

torch::Tensor fused_forward(torch::Tensor x, torch::Tensor weight, float scaling_factor) {
    const auto batch_size = x.size(0);
    const auto input_size = x.size(1);
    const auto hidden_size = weight.size(0);

    auto output = torch::zeros({batch_size, 1}, x.options());

    const int threads_per_block = 256;
    const int num_blocks = (batch_size + threads_per_block - 1) / threads_per_block;

    hipLaunchKernelGGL(fused_kernel, 
        dim3(num_blocks), 
        dim3(threads_per_block), 
        0, 
        at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), 
        weight.data_ptr<float>(), 
        output.data_ptr<float>(), 
        batch_size, 
        input_size, 
        hidden_size, 
        scaling_factor
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__device__ __forceinline__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608028654f * (x + 0.044715f * x * x * x)));
}

__global__ void fused_kernel(
    const float* input, const float* bias, float* output,
    int B, int C, int H_conv, int W_conv,
    int input_C, int input_H, int input_W
) {
    const int bw_idx = blockIdx.x;
    const int b = bw_idx / W_conv;
    const int w = bw_idx % W_conv;
    const int c = threadIdx.x;

    if (b >= B || w >= W_conv) return;

    __shared__ float smin[64];
    __shared__ float ssum;

    float local_sum = 0.0f;
    for (int h = 0; h < H_conv; h++) {
        float min_val = FLT_MAX;
        for (int ch = 0; ch < input_C; ch++) {
            int inp_idx = b * input_C * input_H * input_W + 
                         ch * input_H * input_W + 
                         h * input_W + w;
            min_val = fminf(min_val, input[inp_idx]);
        }
        local_sum += min_val;
    }

    if (threadIdx.x == 0) {
        float sum_gelu = gelu(local_sum);
        ssum = sum_gelu;
    }
    __syncthreads();

    if (c < C) {
        float biased = ssum + bias[c];
        int out_idx = b * C * W_conv + 
                     c * W_conv + 
                     w;
        output[out_idx] = biased;
    }
}

torch::Tensor fused_operation_rocm(
    torch::Tensor input, torch::Tensor bias,
    int B, int C, int H_conv, int W_conv
) {
    auto output = torch::zeros({B, C, 1, W_conv}, input.options());
    int input_C = input.size(1);
    int input_H = input.size(2);
    int input_W = input.size(3);

    dim3 blocks(B * W_conv);
    dim3 threads(C);

    hipLaunchKernelGGL(fused_kernel, 
        blocks, threads, 0, 0, 
        input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
        B, C, H_conv, W_conv,
        input_C, input_H, input_W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_min_softmax_kernel(const float* input, float* output, 
    int batch_size, int num_channels, int depth, int height, int width) {

    extern __shared__ float shared_min[];
    int spatial_pos = blockIdx.x;
    int batch = spatial_pos / (height * width);
    int hw_idx = spatial_pos % (height * width);
    int h = hw_idx / width;
    int w = hw_idx % width;
    int c = threadIdx.x;

    if (c >= num_channels) return;

    float min_val = INFINITY;
    for (int d = 0; d < depth; ++d) {
        int idx = batch * num_channels * depth * height * width +
                c * depth * height * width +
                d * height * width +
                h * width +
                w;
        min_val = fminf(min_val, input[idx]);
    }

    shared_min[c] = min_val;
    __syncthreads();

    float max_val = -INFINITY;
    for (int i = 0; i < num_channels; ++i) {
        max_val = fmaxf(max_val, shared_min[i]);
    }

    float exp_sum = 0.0f;
    for (int i = 0; i < num_channels; ++i) {
        exp_sum += expf(shared_min[i] - max_val);
    }

    if (exp_sum < 1e-12) exp_sum = 1e-12;
    int out_idx = batch * num_channels * height * width +
                c * height * width +
                h * width +
                w;
    output[out_idx] = expf(shared_min[c] - max_val) / exp_sum;
}

torch::Tensor fused_min_softmax_rocm(torch::Tensor input) {
    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int num_channels = sizes[1];
    int depth = sizes[2];
    int height = sizes[3];
    int width = sizes[4];

    auto output = torch::zeros({batch_size, num_channels, height, width}, input.options());
    int num_blocks = batch_size * height * width;
    int block_size = num_channels;
    int shared_mem = num_channels * sizeof(float);

    hipLaunchKernelGGL(fused_min_softmax_kernel, 
        num_blocks, block_size, shared_mem, 0,
        input.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, num_channels, depth, height, width);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* conv_output, 
    float* output, 
    float bias,
    float scaling_factor,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_size = depth * height * width;
    int total_elements = batch_size * spatial_size;
    if (index >= total_elements) return;

    int batch = index / spatial_size;
    int spatial_idx = index % spatial_size;
    int d = spatial_idx / (height * width);
    int h = (spatial_idx % (height * width)) / width;
    int w = spatial_idx % width;

    float sum = 0.0f;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((batch * channels + c) * depth + d) * height * width + h * width + w;
        sum += conv_output[input_idx];
    }
    float val = sum / channels + bias;

    output[index] = tanhf(1.0f) * scaling_factor;
}

torch::Tensor fused_ops_rocm(torch::Tensor conv_output, torch::Tensor bias, float scaling_factor, int channels) {
    auto options = torch::TensorOptions().dtype(conv_output.dtype()).device(conv_output.device());
    int batch_size = conv_output.size(0);
    int depth = conv_output.size(2);
    int height = conv_output.size(3);
    int width = conv_output.size(4);
    int total_elements = batch_size * depth * height * width;
    auto output = torch::empty({batch_size, 1, depth, height, width}, options);

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_ops_kernel, 
        grid_size, block_size, 0, 0,
        conv_output.data_ptr<float>(),
        output.data_ptr<float>(),
        bias.item<float>(),
        scaling_factor,
        batch_size,
        channels,
        depth,
        height,
        width
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_bn_gelu_kernel(const float* input, const float* gamma, const float* beta,
                                     const float* running_mean, const float* running_var,
                                     float eps, int64_t N, int64_t C, float* output) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * C) {
        int c = idx % C;
        float x = input[idx];
        float mean = running_mean[c];
        float var = running_var[c];
        float inv_std = 1.0f / sqrtf(var + eps);
        x = (x - mean) * inv_std * gamma[c] + beta[c];
        x *= 0.5f * (1.0f + ::erff(x * 0.7071067811865475f));
        output[idx] = x;
    }
}

torch::Tensor fused_bn_gelu_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
                                torch::Tensor running_mean, torch::Tensor running_var, float eps) {
    auto output = torch::empty_like(input);
    int64_t N = input.size(0);
    int64_t C = input.size(1);
    int64_t num_elements = N * C;

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bn_gelu_kernel,
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        eps,
        N,
        C,
        output.data_ptr<float>());

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_linear_relu_scale_kernel(const float* x, const float* w, const float* b, float* out, 
                                               int batch_size, int in_features, int out_features, float multiplier) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row >= batch_size || col >= out_features) return;

    float sum = 0.0f;
    for(int k = 0; k < in_features; ++k) {
        sum += x[row * in_features + k] * w[col * in_features + k];
    }

    sum += b[col];
    sum = fmaxf(sum, 0.0f) * multiplier;
    out[row * out_features + col] = sum;
}

torch::Tensor fused_linear_relu_scale_rocm(torch::Tensor x, torch::Tensor w, torch::Tensor b, float divider) {
    auto options = torch::TensorOptions().device(x.device()).dtype(x.dtype());
    auto out = torch::zeros({x.size(0), w.size(0)}, options);

    dim3 threads(16, 16);
    dim3 blocks(
        (x.size(0) + threads.x - 1) / threads.x,
        (w.size(0) + threads.y - 1) / threads.y
    );

    hipLaunchKernelGGL(fused_linear_relu_scale_kernel, 
        blocks, threads, 0, 0, 
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        x.size(0),
        x.size(1),
        w.size(0),
        1.0f / divider
    );

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_gelu_softmax_kernel(const float* input, float* output, int rows, int cols) {
    extern __shared__ float shared_mem[];
    float* shared_gelu = shared_mem;
    float* shared_max = &shared_mem[cols];

    int tid = threadIdx.x;
    int row = blockIdx.x;

    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    for (int idx = tid; idx < cols; idx += blockDim.x) {
        float x = row_input[idx];
        float gelu = 0.5f * x * (1.0f + tanhf(0.797884560802865f * (x + 0.044715f * x * x * x)));
        shared_gelu[idx] = gelu;
    }
    __syncthreads();

    float local_max = -INFINITY;
    for (int idx = tid; idx < cols; idx += blockDim.x) {
        local_max = fmaxf(local_max, shared_gelu[idx]);
    }
    shared_max[tid] = local_max;
    __syncthreads();

    for (int stride = blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + stride]);
        }
        __syncthreads();
    }

    float max_val = shared_max[0];
    __syncthreads();

    float local_sum = 0.0f;
    for (int idx = tid; idx < cols; idx += blockDim.x) {
        float val = shared_gelu[idx] - max_val;
        float exp_val = expf(val);
        shared_gelu[idx] = exp_val;
        local_sum += exp_val;
    }

    shared_max[tid] = local_sum;
    __syncthreads();

    for (int stride = blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            shared_max[tid] += shared_max[tid + stride];
        }
        __syncthreads();
    }

    float sum_exp = shared_max[0];
    float inv_sum = 1.0f / sum_exp;

    for (int idx = tid; idx < cols; idx += blockDim.x) {
        row_output[idx] = shared_gelu[idx] * inv_sum;
    }
}

torch::Tensor fused_gelu_softmax_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int rows = input.size(0);
    int cols = input.size(1);

    dim3 grid(rows);
    int block_size = 256;
    dim3 block(block_size);
    size_t shared_size = (cols + block_size) * sizeof(float);

    hipLaunchKernelGGL(
        fused_gelu_softmax_kernel,
        grid, block, shared_size, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(), output.data_ptr<float>(), rows, cols
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define GROUP_SIZE 256

__global__ void fused_groupnorm_scale_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ scale,
    int N, int C, int H, int W,
    int G, float eps) {

    int n = blockIdx.x;
    int g = blockIdx.y;
    int num_channels_per_group = C / G;
    int num_pixels = num_channels_per_group * H * W;

    extern __shared__ float shm[];
    float* mean_shm = shm;
    float* var_shm = &shm[GROUP_SIZE];

    float sum = 0.0f;
    float sq_sum = 0.0f;
    int tid = threadIdx.x;

    for (int c = g * num_channels_per_group; c < (g+1)*num_channels_per_group; c++) {
        for (int hw = tid; hw < H*W; hw += blockDim.x) {
            int h = hw / W;
            int w = hw % W;
            float val = input[(((n * C + c) * H) + h) * W + w];
            sum += val;
            sq_sum += val * val;
        }
    }

    mean_shm[tid] = sum;
    var_shm[tid] = sq_sum;
    __syncthreads();

    for (int s=blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            mean_shm[tid] += mean_shm[tid + s];
            var_shm[tid] += var_shm[tid + s];
        }
        __syncthreads();
    }

    float final_mean = mean_shm[0] / num_pixels;
    float final_var = (var_shm[0] / num_pixels) - (final_mean * final_mean);
    float inv_std = rsqrtf(final_var + eps);

    for (int c = g * num_channels_per_group; c < (g+1)*num_channels_per_group; c++) {
        for (int hw = tid; hw < H*W; hw += blockDim.x) {
            int h = hw / W;
            int w = hw % W;
            int idx = (((n * C + c) * H) + h) * W + w;
            float norm_val = (input[idx] - final_mean) * inv_std;
            float w_scale = weight[c] * scale[c];
            float b_scale = bias[c] * scale[c];
            output[idx] = norm_val * w_scale + b_scale;
        }
    }
}

torch::Tensor fused_groupnorm_scale_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor scale, int num_groups, float eps) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    auto output = torch::empty_like(input);

    dim3 grid(N, num_groups);
    int block_size = std::min(H*W, 256);

    fused_groupnorm_scale_kernel<<<grid, block_size, 2*block_size*sizeof(float)>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        N, C, H, W, num_groups, eps);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_min_clamp_dropout_kernel(const float* x, float* out, float min_val, float max_val, 
float dropout_p, bool training, int size, float inv_dropout, int seed) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        unsigned int rand = (seed + idx) * 1103515245 + 12345;
        float mask = (rand / 4294967296.0f) > dropout_p ? 1.0f : 0.0f;

        float val = x[idx];
        val = fminf(val, min_val);
        val = fmaxf(fminf(val, max_val), min_val);

        if (training) {
            val = mask * val * inv_dropout;
        }
        out[idx] = val;
    }
}

torch::Tensor fused_min_clamp_dropout_rocm(torch::Tensor x, float min_val, float max_val, float dropout_p, bool training) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    int seed = torch::randint(1e8, {}, x.options().dtype(torch::kInt)).item<int>();
    float inv_dropout = 1.0f / (1.0f - dropout_p);

    hipLaunchKernelGGL(fused_min_clamp_dropout_kernel, 
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), out.data_ptr<float>(), min_val, max_val, 
        dropout_p, training, size, inv_dropout, seed
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__global__ void scaled_min_kernel(const float* input, float* output, float scale_factor, int channels, int height, int width) {
    int batch = blockIdx.z;
    int w = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;

    if (h >= height || w >= width) return;

    float min_val = FLT_MAX;
    for (int c = 0; c < channels; ++c) {
        int input_idx = batch * channels * height * width + c * height * width + h * width + w;
        float val = input[input_idx] * scale_factor;
        min_val = fminf(min_val, val);
    }

    int output_idx = batch * height * width + h * width + w;
    output[output_idx] = min_val;
}

torch::Tensor scaled_min_rocm(torch::Tensor input, float scale_factor) {
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(input.dim() == 4, "Input must be 4D");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    auto output = torch::zeros({batch_size, 1, height, width}, input.options());

    dim3 block(16, 16);
    dim3 grid(
        (width + block.x - 1) / block.x,
        (height + block.y - 1) / block.y,
        batch_size
    );

    hipLaunchKernelGGL(scaled_min_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(), scale_factor, channels, height, width);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_ops_kernel(const float* input, float add_val, float mult_val, float* output, int numel) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        float val = input[idx] + add_val;
        val = fminf(val, 0.0f);
        val = 0.5f * val * (1.0f + tanhf(0.7978845608028654f * (val + 0.044715f * val * val * val)));
        output[idx] = val * mult_val;
    }
}

torch::Tensor fused_ops_rocm(torch::Tensor x, float add_value, float multiply_value) {
    auto output = torch::zeros_like(x);
    int numel = x.numel();
    const int block_size = 256;
    int grid_size = (numel + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_ops_kernel, 
        grid_size, block_size, 0, at::cuda::getCurrentHIPStream(), 
        x.data_ptr<float>(), add_value, multiply_value, output.data_ptr<float>(), numel);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_kernel(const float* x, float constant, const float* bias, float scale, float* out, 
                           int elements, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < elements) {
        int c = (idx / (H * W)) % C;
        float val = min(x[idx], constant);
        val += bias[c];
        out[idx] = val * scale;
    }
}

torch::Tensor fused_min_add_mul(torch::Tensor x, float constant_val, torch::Tensor bias, float scaling) {
    auto out = torch::empty_like(x);
    int elements = x.numel();
    auto s = x.sizes();
    int C = s[1], H = s[2], W = s[3];

    hipLaunchKernelGGL(fused_kernel, 
        (elements+255)/256, 256, 0, 0,
        x.data_ptr<float>(), constant_val, bias.data_ptr<float>(), scaling,
        out.data_ptr<float>(), elements, C, H, W
    );

    return out;
}

#include <torch/extension.h>
