__global__ void relu_add_bias_kernel(const float* input, const float* bias, float* output, int total_size, int channels, int hw_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_size) return;

    int c = (idx % (channels * hw_size)) / hw_size;
    output[idx] = fmaxf(input[idx], 0.0f) + bias[c];
}

torch::Tensor fused_relu_add_rocm(torch::Tensor input, torch::Tensor bias) {
    auto output = torch::empty_like(input);
    int total_elements = input.numel();
