    hipLaunchKernelGGL(
        relu_add_bias_kernel, 
        grid_size, block_size, 0, 0,
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        total_elements,
        channels,
        hw_size
    );

