}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_linear_sigmoid_kernel(const float* input, const float* weight, const float* bias, float* output, int input_size, int hidden_size, int batch_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * hidden_size) return;

    int row = idx / hidden_size;
    int col = idx % hidden_size;

    float sum = 0.0f;
    for(int k=0; k<input_size; k++) {
        sum += input[row*input_size + k] * weight[col*input_size + k];
    }
    sum += bias[col];
    output[idx] = 1.0f / (1.0f + expf(-sum));
}

torch::Tensor fused_linear_sigmoid_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    auto batch_size = input.size(0);
    auto input_size = input.size(1);
    auto hidden_size = weight.size(0);

    auto output = torch::empty({batch_size, hidden_size}, input.options());

    int total = batch_size * hidden_size;
    int block = 256;
    int grid = (total + block - 1) / block;

    hipLaunchKernelGGL(fused_linear_sigmoid_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        output.data_ptr<float>(), input_size, hidden_size, batch_size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_conv_gap_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int in_channels,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int input_height,
    int input_width,
    int output_area
) {
    int batch = blockIdx.z;
    int out_ch = blockIdx.y;
    int element = blockIdx.x * blockDim.x + threadIdx.x;

    if (element >= 1) return;

    float sum = bias != nullptr ? bias[out_ch] * output_area : 0.0f;

    for (int in_ch = 0; in_ch < in_channels; ++in_ch) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                float weight_val = weight[in_ch * out_channels * kernel_size * kernel_size + 
                                        out_ch * kernel_size * kernel_size + kh * kernel_size + kw];
                for (int h = 0; h < input_height; ++h) {
                    for (int w = 0; w < input_width; ++w) {
                        sum += input[batch * in_channels * input_height * input_width + 
                                   in_ch * input_height * input_width + 
                                   h * input_width + w] * weight_val;
                    }
                }
            }
        }
    }

    output[batch * out_channels + out_ch] = sum / output_area;
}

torch::Tensor fused_conv_gap_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int output_area
) {
    int batch_size = input.size(0);
    int out_channels = weight.size(1);
    auto output = torch::zeros({batch_size, out_channels, 1, 1}, input.options());

    dim3 blocks(1, out_channels, batch_size);
    fused_conv_gap_kernel<<<blocks, 256>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        input.size(1),
        out_channels,
        kernel_size,
        stride,
        padding,
        output_padding,
        input.size(2),
        input.size(3),
        output_area
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_leaky_multiplier_kernel(const float* x, const float* multiplier, float* out, 
                                              int B, int C, int D, int H, int W, float leaky_slope, 
                                              int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int elements_per_channel = D * H * W;
    int index_in_batch = idx % (C * elements_per_channel);
    int c = index_in_batch / elements_per_channel;

    float val = x[idx];
    val = val > 0 ? val : val * leaky_slope;
    val *= multiplier[c];
    val = val > 0 ? val : val * leaky_slope;
    out[idx] = val;
}

torch::Tensor fused_leaky_multiplier_rocm(torch::Tensor x, torch::Tensor multiplier, double leaky_slope) {
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N, C, D, H, W)");
    TORCH_CHECK(multiplier.device() == x.device(), "multiplier must be on the same device as x");
    TORCH_CHECK(multiplier.dim() == 4, "multiplier must be 4D (C, 1, 1, 1)");
    TORCH_CHECK(multiplier.size(0) == x.size(1), "multiplier size must match x's channel count");

    auto out = torch::zeros_like(x);
    int total_elements = x.numel();
    float leaky_slope_float = static_cast<float>(leaky_slope);
    int B = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;
    hipStream_t stream = at::hip::getCurrentHIPStream();

    hipLaunchKernelGGL(fused_leaky_multiplier_kernel,
        dim3(num_blocks),
        dim3(block_size),
        0,
        stream,
        x.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W,
        leaky_slope_float,
        total_elements
    );

    return out;
}

