#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_activation_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];
        float y;
        if (x >= 3.0f) {
            y = x;
        } else if (x >= 0.0f) {
            y = x * (x + 3.0f) / 6.0f;
        } else {
            y = 0.0f;
        }
        output[idx] = y > 0.0f ? y : 0.0f;
    }
}

torch::Tensor fused_activation_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_activation_kernel, 
        dim3(num_blocks), dim3(block_size), 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(), num_elements);
    return output;
}

