__global__ void fused_maxpool_sum_kernel(const float* input, float* output, int batch_size, int in_channels, int in_depth, int in_height, int in_width, int kernel_size, int out_depth, int out_height, int out_width) {
    int d_out = blockIdx.x;
    int h_out = blockIdx.y;
    int w_out = blockIdx.z;
    int b = threadIdx.x;

    if (b >= batch_size || d_out >= out_depth || h_out >= out_height || w_out >= out_width) return;

    float sum_val = 0.0f;

    for (int c = 0; c < in_channels; ++c) {
        float max_val = -INFINITY;
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int d_in = d_out * kernel_size + kd;
                    int h_in = h_out * kernel_size + kh;
                    int w_in = w_out * kernel_size + kw;
                    if (d_in < in_depth && h_in < in_height && w_in < in_width) {
                        int idx = (((b * in_channels + c) * in_depth + d_in) * in_height + h_in) * in_width + w_in;
                        float val = input[idx];
                        if (val > max_val) max_val = val;
                    }
                }
            }
        }
        sum_val += max_val;
    }

    int out_idx = ((b * out_depth + d_out) * out_height + h_out) * out_width + w_out;
    output[out_idx] = sum_val;
}

torch::Tensor fused_maxpool_sum_rocm(torch::Tensor input) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);
    int kernel_size = 3;
    int out_depth = in_depth / kernel_size;
    int out_height = in_height / kernel_size;
    int out_width = in_width / kernel_size;

    auto output = torch::zeros({batch_size, 1, out_depth, out_height, out_width}, input.options());

    dim3 grid(out_depth, out_height, out_width);
    int block_size = std::min(batch_size, 64);

    hipLaunchKernelGGL(
        fused_maxpool_sum_kernel,
        grid, dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, in_channels, in_depth, in_height, in_width, kernel_size,
        out_depth, out_height, out_width
    );

    return output;
}

