__global__ void fused_tanh_scale_add_bias_kernel(
    const float* input, float* output, const float* bias,
    float scaling_factor, int num_elements, int C, int HxW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int channel = (idx / HxW) % C;
    float val = input[idx];
    val = tanhf(val);
    val *= scaling_factor;
    val += bias[channel];
    output[idx] = val;
}

torch::Tensor fused_tanh_scale_add_bias(
    torch::Tensor input, torch::Tensor bias, float scaling_factor
) {
    CHECK_INPUT(input);
    CHECK_INPUT(bias);

    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int C = bias.size(0);
    auto sizes = input.sizes();
    int HxW = sizes[2] * sizes[3];

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    const float* input_data = input.data_ptr<float>();
    float* output_data = output.data_ptr<float>();
    const float* bias_data = bias.data_ptr<float>();

    hipLaunchKernelGGL(fused_tanh_scale_add_bias_kernel,
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        input_data, output_data, bias_data, scaling_factor,
        num_elements, C, HxW
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_swish_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, int batch_size, int num_features, int num_groups, float eps) {

    extern __shared__ float shared_data[];
    float* shared_sum = shared_data;
    float* shared_sum_sq = &shared_data[blockDim.x];

    int group_id = blockIdx.x % num_groups;
    int sample_id = blockIdx.x / num_groups;
    int channels_per_group = num_features / num_groups;

    int channel_start = group_id * channels_per_group;
    int idx = sample_id * num_features + channel_start;

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        float val = input[idx + i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    shared_sum[threadIdx.x] = thread_sum;
    shared_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (threadIdx.x < s) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + s];
            shared_sum_sq[threadIdx.x] += shared_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = shared_sum[0] / channels_per_group;
    float var = (shared_sum_sq[0] / channels_per_group) - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        int pos = idx + i;
        float x = (input[pos] - mean) * inv_std;
        x = x * gamma[channel_start + i] + beta[channel_start + i];
        x *= 1.0f / (1.0f + expf(-x));
        output[pos] = x;
    }
}

torch::Tensor fused_group_norm_swish_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int num_features = input.size(1);

    dim3 grid(batch_size * num_groups);
    dim3 block(256);
    size_t shared_mem = 2 * block.x * sizeof(float);

    group_norm_swish_kernel<<<grid, block, shared_mem>>>(
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        output.data_ptr<float>(), batch_size, num_features, num_groups, eps);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_layernorm_gelu_scaling_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, float scaling_factor, float eps,
    int N, int C, int D, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C * D * H * W) return;

    int c = (idx / (D * H * W)) % C;

    float mean = 0.0f;
    float var = 0.0f;
    const float* group_input = input + (idx / W) * W;

    for(int i = 0; i < W; ++i) {
        mean += group_input[i];
    }
    mean /= W;

    for(int i = 0; i < W; ++i) {
        var += (group_input[i] - mean) * (group_input[i] - mean);
    }
    var /= W;

    float x = input[idx];
    float normalized = (x - mean) / sqrt(var + eps);
    float scaled = normalized * gamma[c] + beta[c];
    float gelu = 0.5f * scaled * (1.0f + erff(scaled / 1.41421356237f));
    output[idx] = gelu * scaling_factor;
}

torch::Tensor fused_op_rocm(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
    float scaling_factor, float eps
) {
    auto out = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_layernorm_gelu_scaling_kernel,
        grid_size, block_size, 0, 0,
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        out.data_ptr<float>(), scaling_factor, eps,
        input.size(0), input.size(1), input.size(2), input.size(3), input.size(4)
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_act_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        x = fmaxf(0.01f * x, x);
        x = fmaxf(0.01f * x, x);
        const float kSqrtTwoOverPi = 0.7978845608028654f;
        float inner = x + 0.044715f * x * x * x;
        float gelu_x = 0.5f * x * (1.0f + tanhf(kSqrtTwoOverPi * inner));
        inner = gelu_x + 0.044715f * gelu_x * gelu_x * gelu_x;
        gelu_x = 0.5f * gelu_x * (1.0f + tanhf(kSqrtTwoOverPi * inner));
        output[idx] = gelu_x;
    }
}

torch::Tensor fused_activations_rocm(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    hipLaunchKernelGGL(fused_act_kernel, 
        dim3(num_blocks), dim3(block_size), 0, 0, 
        x.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_matmul_dropout_kernel(
    const float* x, const float* w, const float* bias, const float* mask,
    float* out, int B, int in_dim, int out_dim
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < B && col < out_dim) {
        float val = 0.0f;
        for (int k = 0; k < in_dim; k++) {
            val += x[row * in_dim + k] * w[k * out_dim + col];
        }
        val += bias[col];
        out[row * out_dim + col] = val * mask[row * out_dim + col];
    }
}

torch::Tensor fused_matmul_dropout(
    torch::Tensor x, torch::Tensor w, torch::Tensor bias, torch::Tensor mask
) {
    int B = x.size(0);
    int in_dim = x.size(1);
    int out_dim = w.size(0);
    auto out = torch::zeros({B, out_dim}, x.options());

    dim3 blocks((B + 15) / 16, (out_dim + 15) / 16);
    dim3 threads(16, 16);

    hipLaunchKernelGGL(
        fused_matmul_dropout_kernel, 
        blocks, threads, 0, 0,
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        bias.data_ptr<float>(),
        mask.data_ptr<float>(),
        out.data_ptr<float>(),
        B, in_dim, out_dim
    );

    return out;
}

