#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_instance_norm_div_kernel(const float* input, float* output, 
                                               int batch_size, int channels, 
                                               int h, int w, float eps, float div) {
    int i = blockIdx.x; // batch index
    int c = blockIdx.y; // channel index
    int tid = threadIdx.x;

    int elements = h * w;
    int offset = (i * channels * elements) + (c * elements);

    extern __shared__ float sdata[];
    float* sum_shared = sdata;
    float* sum_sq_shared = &sum_shared[blockDim.x];

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int idx = tid; idx < elements; idx += blockDim.x) {
        float val = input[offset + idx];
        sum += val;
        sum_sq += val * val;
    }

    sum_shared[tid] = sum;
    sum_sq_shared[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sum_shared[tid] += sum_shared[tid + s];
            sum_sq_shared[tid] += sum_sq_shared[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = sum_shared[0] / elements;
        float var = (sum_sq_shared[0] / elements) - (mean * mean);
        float inv_std = rsqrt(var + eps);
        sum_shared[0] = mean;
        sum_sq_shared[0] = inv_std / div;
    }
    __syncthreads();

    float mean = sum_shared[0];
    float inv_std_div = sum_sq_shared[0];

    for (int idx = tid; idx < elements; idx += blockDim.x) {
        float val = input[offset + idx];
        output[offset + idx] = (val - mean) * inv_std_div;
    }
}

torch::Tensor fused_instance_norm_div_rocm(torch::Tensor input, int batch_size, int channels, 
                                           int h, int w, float eps, float div) {
    auto output = torch::empty_like(input);
    int elements = h * w;
    dim3 grid(batch_size, channels);
    int block_size = 1024;
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    fused_instance_norm_div_kernel<<<grid, block_size, shared_mem_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), 
        batch_size, channels, h, w, eps, div);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_op_kernel(const float* input, const float* bias, float* output, int num_elements,
                                int C, int H, int W, float scaling_factor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int channel_stride = H * W;
    int c = (idx / channel_stride) % C;

    float val = input[idx] + bias[c];
    val = fmaxf(0.0f, fminf(val, 1.0f));
    val *= scaling_factor;
    val = fmaxf(0.0f, fminf(val, 1.0f));
    val /= scaling_factor;
    output[idx] = val;
}

torch::Tensor fused_ops_rocm(torch::Tensor x, torch::Tensor bias, float scaling_factor) {
    auto out = torch::empty_like(x);
    if (!x.is_contiguous()) x = x.contiguous();
    if (!bias.is_contiguous()) bias = bias.contiguous();

    float* input_ptr = x.data_ptr<float>();
    float* bias_ptr = bias.data_ptr<float>();
    float* output_ptr = out.data_ptr<float>();

    int num_elements = x.numel();
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_op_kernel, 
                       dim3(grid_size), 
                       dim3(block_size),
                       0,
                       at::hip::getCurrentHIPStream(),
                       input_ptr,
                       bias_ptr,
                       output_ptr,
                       num_elements,
                       C,
                       H,
                       W,
                       scaling_factor);

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_maxpool_globalavg_clamp_kernel(const float* input, float* output,
                                                   int batch_size, int num_channels,
                                                   int input_depth, int input_height, int input_width,
                                                   int kernel_size,
                                                   float clamp_min, float clamp_max) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;

    if (batch_idx >= batch_size || channel_idx >= num_channels) return;

    int output_depth = input_depth / kernel_size;
    int output_height = input_height / kernel_size;
    int output_width = input_width / kernel_size;
    int total_elements = output_depth * output_height * output_width;

    int input_offset = batch_idx * num_channels * input_depth * input_height * input_width
                       + channel_idx * input_depth * input_height * input_width;

    float sum = 0.0f;
    for (int d = 0; d < output_depth; ++d) {
        for (int h = 0; h < output_height; ++h) {
            for (int w = 0; w < output_width; ++w) {
                float max_val = -INFINITY;
                for (int kd = 0; kd < kernel_size; ++kd) {
                    for (int kh = 0; kh < kernel_size; ++kh) {
                        for (int kw = 0; kw < kernel_size; ++kw) {
                            int id = d * kernel_size + kd;
                            int ih = h * kernel_size + kh;
                            int iw = w * kernel_size + kw;
                            if (id >= input_depth || ih >= input_height || iw >= input_width) continue;
                            int idx = input_offset + id * (input_height * input_width)
                                                   + ih * input_width + iw;
                            float val = input[idx];
                            max_val = fmaxf(max_val, val);
                        }
                    }
                }
                sum += max_val;
            }
        }
    }
    float avg = sum / total_elements;
    avg = fminf(fmaxf(avg, clamp_min), clamp_max);
    int output_idx = batch_idx * num_channels * 1 * 1 * 1 + channel_idx * 1 * 1 * 1;
    output[output_idx] = avg;
}

torch::Tensor fused_maxpool_globalavg_clamp(torch::Tensor input, int kernel_size,
                                           float clamp_min, float clamp_max) {
    auto batch_size = input.size(0);
    auto num_channels = input.size(1);
    auto input_depth = input.size(2);
    auto input_height = input.size(3);
    auto input_width = input.size(4);

    auto output = torch::zeros({batch_size, num_channels, 1, 1, 1}, input.options());

    dim3 grid(batch_size, num_channels);
    hipLaunchKernelGGL(fused_maxpool_globalavg_clamp_kernel, grid, 1, 0, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_channels,
        input_depth,
        input_height,
        input_width,
        kernel_size,
        clamp_min,
        clamp_max);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__global__ void fused_kernel(
    const float* input, const float* bias, float scaling_factor, float* output,
    int batch_size, int channels, int height, int width) {

    int spatial_pos = blockIdx.x;
    int n = spatial_pos / (height * width);
    int hw = spatial_pos % (height * width);
    int h = hw / width;
    int w = hw % width;

    extern __shared__ float smem[];
    float* max_shared = smem;
    float* sum_shared = smem + blockDim.x;

    float max_val = -FLT_MAX;
    for (int c = threadIdx.x; c < channels; c += blockDim.x) {
        int idx = (((n * channels + c) * height + h) * width) + w;
        max_val = fmaxf(max_val, input[idx]);
    }

    max_shared[threadIdx.x] = max_val;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            max_shared[threadIdx.x] = fmaxf(max_shared[threadIdx.x], max_shared[threadIdx.x+s]);
        }
        __syncthreads();
    }

    float max_value = max_shared[0];
    __syncthreads();

    float sum_exp = 0.0f;
    for (int c = threadIdx.x; c < channels; c += blockDim.x) {
        int idx = (((n * channels + c) * height + h) * width) + w;
        sum_exp += expf(input[idx] - max_value);
    }

    sum_shared[threadIdx.x] = sum_exp;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sum_shared[threadIdx.x] += sum_shared[threadIdx.x+s];
        }
        __syncthreads();
    }

    float sum_exp_val = sum_shared[0];

    for (int c = threadIdx.x; c < channels; c += blockDim.x) {
        int idx = (((n * channels + c) * height + h) * width) + w;
        float val = input[idx];
        float softmax_val = expf(val - max_value)/sum_exp_val;
        float result = 1.0f/(1.0f + expf(-(softmax_val + bias[c])*scaling_factor));
        output[idx] = result;
    }
}

torch::Tensor fused_softmax_bias_scale_sigmoid_rocm(torch::Tensor input, torch::Tensor bias, float scaling_factor) {
    auto output = torch::zeros_like(input);
    int batch = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    int blocks = batch * height * width;
    int threads = 256;
    size_t shared_mem = 2 * threads * sizeof(float);

    hipLaunchKernelGGL(fused_kernel, dim3(blocks), dim3(threads), shared_mem, 0,
        input.data_ptr<float>(), 
        bias.data_ptr<float>(),
        scaling_factor,
        output.data_ptr<float>(),
        batch, channels, height, width
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_linear_sum_kernel(const float* x, const float* sum_weight, float sum_bias, float* output, int batch_size, int in_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size) return;

    float val = sum_bias;
    for (int k = 0; k < in_features; ++k) {
        val += x[idx * in_features + k] * sum_weight[k];
    }
    output[idx] = val;
}

torch::Tensor fused_linear_sum_rocm(torch::Tensor x, torch::Tensor sum_weight, float sum_bias) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    auto output = torch::empty({batch_size}, x.options());

    const int block_size = 256;
    int num_blocks = (batch_size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_linear_sum_kernel,
        dim3(num_blocks), dim3(block_size), 0, 0,
        x.data_ptr<float>(),
        sum_weight.data_ptr<float>(),
        sum_bias,
        output.data_ptr<float>(),
        batch_size,
        in_features
    );

    return output.unsqueeze(1);
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_pool_sigmoid_kernel(const float* input, float* output, 
                                        int batch_size, int channels, 
                                        int in_h, int in_w, 
                                        int pool_size) {
    int out_h_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int out_w_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int batch_ch = blockIdx.z;

    int b = batch_ch / channels;
    int c = batch_ch % channels;

    int out_h = in_h / pool_size;
    int out_w = in_w / pool_size;

    if (b >= batch_size || c >= channels || out_h_idx >= out_h || out_w_idx >= out_w) return;

    int h_start = out_h_idx * pool_size;
    int h_end = h_start + pool_size;
    h_end = min(h_end, in_h);

    int w_start = out_w_idx * pool_size;
    int w_end = w_start + pool_size;
    w_end = min(w_end, in_w);

    float sum = 0.0f;
    for (int h = h_start; h < h_end; ++h) {
        for (int w = w_start; w < w_end; ++w) {
            sum += input[b * channels * in_h * in_w + c * in_h * in_w + h * in_w + w];
        }
    }

    float avg = sum / ((h_end - h_start) * (w_end - w_start));
    output[batch_ch * out_h * out_w + out_h_idx * out_w + out_w_idx] = 1.0f / (1.0f + expf(-avg));
}

torch::Tensor fused_pool_act_rocm(torch::Tensor input, int pool_size) {
    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int channels = sizes[1];
    int in_h = sizes[2];
    int in_w = sizes[3];
    int out_h = in_h / pool_size;
    int out_w = in_w / pool_size;

    auto output = torch::zeros({batch_size, channels, out_h, out_w}, input.options());

    dim3 block(16, 16);
    dim3 grid(
        (out_w + block.x - 1) / block.x,
        (out_h + block.y - 1) / block.y,
        batch_size * channels
    );

    hipLaunchKernelGGL(fused_pool_sigmoid_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(), 
        batch_size, channels, in_h, in_w, pool_size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_relu_hardswish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        x = fmaxf(0.0f, x);
        float temp = (x + 3.0f) / 6.0f;
        temp = fminf(temp, 1.0f);
        output[idx] = x * temp;
    }
}

torch::Tensor fused_relu_hardswish_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_relu_hardswish_kernel, 
        dim3(num_blocks), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_mean_kernel(const float* input, float* output, const float* gamma, const float* beta,
                                       int batch_size, int channels, int depth, int height, int width,
                                       int num_groups, float eps) {
    int outer_size = batch_size * num_groups;
    int group_channels = channels / num_groups;
    int inner_size = group_channels * depth * height * width;

    extern __shared__ float shared[];
    float* sum_shared = shared;
    float* sum_sq_shared = &shared[outer_size];

    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (outer_idx >= outer_size) return;

    int batch = outer_idx / num_groups;
    int group = outer_idx % num_groups;

    const float* group_input = input + (batch * channels + group * group_channels) * depth * height * width;
    float sum = 0.0f, sum_sq = 0.0f;

    for (int i = 0; i < inner_size; ++i) {
        float val = group_input[i];
        sum += val;
        sum_sq += val * val;
    }

    sum_shared[outer_idx] = sum;
    sum_sq_shared[outer_idx] = sum_sq;

    __syncthreads();

    float mean = sum_shared[outer_idx] / inner_size;
    float var = sum_sq_shared[outer_idx] / inner_size - mean * mean;
    float inv_std = rsqrtf(var + eps);

    float sum_out = 0.0f;
    for (int i = 0; i < inner_size; ++i) {
        float val = (group_input[i] - mean) * inv_std;
        int channel = group * group_channels + (i / (depth * height * width)) % group_channels;
        val = val * gamma[channel] + beta[channel];
        sum_out += val;
    }

    atomicAdd(&output[batch], sum_out);
}

torch::Tensor fused_group_norm_mean_rocm(torch::Tensor input, int num_groups, torch::Tensor gamma, torch::Tensor beta, float eps) {
    int batch_size = input.size(0);
    auto output = torch::zeros(batch_size, input.options());

    int channels = input.size(1);
    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    dim3 grid_dim((batch_size * num_groups + 127) / 128);
    dim3 block_dim(128);
    int shared_size = 2 * batch_size * num_groups * sizeof(float);

    hipLaunchKernelGGL(
        group_norm_mean_kernel,
        grid_dim, block_dim, shared_size, at::cuda::getCurrentHIPStream(),
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        batch_size, channels, depth, height, width,
        num_groups, eps
    );

    output /= (channels * depth * height * width);
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void subtract_hardswish_kernel(const float* input, float subtract_value, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx] - subtract_value;
        float relu6_val = fminf(fmaxf(val + 3.0f, 0.0f), 6.0f);
        output[idx] = val * relu6_val / 6.0f;
    }
}

torch::Tensor subtract_hardswish(torch::Tensor input, float subtract_value) {
    auto num_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(subtract_hardswish_kernel, 
        num_blocks, block_size, 0, 0,
        input.data_ptr<float>(),
        subtract_value,
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}

__global__ void maxpool_mish_kernel(const float* input, float* output, 
    int batches, int channels, int in_h, int in_w, int out_h, int out_w) {

    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int c = blockIdx.y;
    int n = blockIdx.z;

    if (n >= batches || c >= channels) return;

    int ph = (out_idx) / out_w;
    int pw = (out_idx) % out_w;
    if (ph >= out_h || pw >= out_w) return;

    int h_start = ph * 2;
    int h_end = h_start + 2 < in_h ? h_start + 2 : in_h;
    int w_start = pw * 2;
    int w_end = w_start + 2 < in_w ? w_start + 2 : in_w;

    float max_val = -INFINITY;
    for (int h = h_start; h < h_end; ++h) {
        for (int w = w_start; w < w_end; ++w) {
            int inp_idx = ((n * channels + c) * in_h + h) * in_w + w;
            max_val = fmaxf(max_val, input[inp_idx]);
        }
    }

    float softplus = log1pf(expf(max_val));
    float mish = max_val * tanhf(softplus);
    int out_index = ((n * channels + c) * out_h + ph) * out_w + pw;
    output[out_index] = mish;
}

torch::Tensor maxpool_mish(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 4, "Input must be 4D tensor");
    int batches = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);
    int out_h = in_h / 2;
    int out_w = in_w / 2;

    auto output = torch::empty({batches, channels, out_h, out_w}, input.options());

    dim3 threads(256);
    dim3 blocks((out_h * out_w + threads.x - 1) / threads.x, channels, batches);

    hipLaunchKernelGGL(maxpool_mish_kernel, blocks, threads, 0, 0, 
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batches, channels, in_h, in_w, out_h, out_w
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void linear_fused_kernel(const float* x, const float* weight, const float* bias, float* out, int batch_size, int in_features, int out_features) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < batch_size && col < out_features) {
        float sum = 0.0f;
        for(int k = 0; k < in_features; k++) {
            sum += x[row * in_features + k] * weight[col * in_features + k];
        }
        sum += bias[col];
        out[row * out_features + col] = sum;
    }
}

torch::Tensor linear_fused_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);
    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1) / block.x, (out_features + block.y - 1) / block.y);

    hipLaunchKernelGGL(linear_fused_kernel, grid, block, 0, 0, 
        x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), 
        out.data_ptr<float>(), batch_size, in_features, out_features);

    return out;
}

__global__ void double_mish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];

        float sp1 = logf(1.0f + expf(x));
        float mish1 = x * tanhf(sp1);

        float sp2 = logf(1.0f + expf(mish1));
        output[idx] = mish1 * tanhf(sp2);
    }
}

torch::Tensor double_mish_rocm(torch::Tensor input) {
    auto output = torch::zeros_like(input);
    int size = input.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(double_mish_kernel, num_blocks, block_size, 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

template <typename scalar_t>
__global__ void scale_softmax_kernel(
    const scalar_t* input,
    const scalar_t* scale,
    scalar_t* output,
    int batch_size,
    int num_features
) {
    extern __shared__ __align__(sizeof(scalar_t)) unsigned char shared_mem[];
    scalar_t* shared_max = reinterpret_cast<scalar_t*>(shared_mem);
    scalar_t* shared_sum = shared_max + blockDim.x;

    int row = blockIdx.x;
    int tid = threadIdx.x;

    scalar_t local_max = -INFINITY;
    scalar_t local_sum = 0;

    if (row >= batch_size) return;

    for (int i = tid; i < num_features; i += blockDim.x) {
        scalar_t value = input[row * num_features + i] * scale[0];
        local_max = (value > local_max) ? value : local_max;
    }

    shared_max[tid] = local_max;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s && (shared_max[tid + s] > shared_max[tid])) {
            shared_max[tid] = shared_max[tid + s];
        }
        __syncthreads();
    }

    __syncthreads();
    scalar_t row_max = shared_max[0];

    for (int i = tid; i < num_features; i += blockDim.x) {
        scalar_t value = input[row * num_features + i] * scale[0];
        scalar_t exp_val = exp(value - row_max);
        output[row * num_features + i] = exp_val;
        local_sum += exp_val;
    }

    shared_sum[tid] = local_sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    scalar_t row_sum = shared_sum[0];
    __syncthreads();

    for (int i = tid; i < num_features; i += blockDim.x) {
        output[row * num_features + i] /= row_sum;
    }
}

torch::Tensor scale_softmax_rocm(torch::Tensor input, torch::Tensor scale) {
    TORCH_CHECK(input.dim() == 2, "input must be 2D");
    TORCH_CHECK(scale.numel() == 1, "scale must be scalar");

    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int num_features = input.size(1);

    int block_size = 256;
    dim3 grid(batch_size);
    dim3 block(block_size);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "scale_softmax_rocm", ([&] {
        size_t shared_size = 2 * block_size * sizeof(scalar_t);
        scale_softmax_kernel<scalar_t><<<grid, block, shared_size>>>(
            input.data_ptr<scalar_t>(),
            scale.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch_size,
            num_features
        );
    }));

    return output;
}

#include <torch/extension.h>
