__global__ void fused_bn_scaling_kernel(const float* input, const float* a, const float* b, float* output, int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;
    if (idx >= total_elements) return;

    int c = (idx / (H * W)) % C;
    output[idx] = input[idx] * a[c] + b[c];
}

torch::Tensor fused_bn_scaling_rocm(torch::Tensor input, torch::Tensor a, torch::Tensor b) {
    auto output = torch::empty_like(input);
    auto sizes = input.sizes();
    int N = sizes[0], C = sizes[1], H = sizes[2], W = sizes[3];
    int num_elements = input.numel();

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bn_scaling_kernel, num_blocks, block_size, 0, 0, 
        input.data_ptr<float>(), 
        a.data_ptr<float>(), 
        b.data_ptr<float>(), 
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_min_tanh_kernel(
    const float* input,
    float* output,
    int batch_size,
    int out_channels,
    int height,
    int width
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int num_positions = batch_size * height * width;
    if (tid >= num_positions) return;

    int n = tid / (height * width);
    int remaining = tid % (height * width);
    int h = remaining / width;
    int w = remaining % width;

    int base = n * out_channels * height * width + h * width + w;
    float min_val = INFINITY;

    for (int c = 0; c < out_channels; ++c) {
        float val = input[base + c * height * width];
        min_val = fminf(min_val, val);
    }

    min_val = tanhf(min_val);
    min_val = tanhf(min_val);

    int output_idx = n * height * width + h * width + w;
    output[output_idx] = min_val;
}

torch::Tensor fused_min_tanh_rocm(torch::Tensor input) {
    auto contiguous_input = input.contiguous();
    auto batch_size = contiguous_input.size(0);
    int out_channels = contiguous_input.size(1);
    int height = contiguous_input.size(2);
    int width = contiguous_input.size(3);

    auto output = torch::zeros({batch_size, 1, height, width}, contiguous_input.options());

    int total_positions = batch_size * height * width;
    const int block_size = 256;
    int num_blocks = (total_positions + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_min_tanh_kernel,
        num_blocks,
        block_size,
        0,
        0,
        contiguous_input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_channels,
        height,
        width
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_kernel(
    const float* input, float* output,
    const float* weight, const float* bias,
    int n_batch,
    int n_chnls,
    int D, int H, int W,
    int groups, float epsilon) {

    extern __shared__ float smem[];
    int n = blockIdx.x;
    int g = blockIdx.y;
    int C_per_group = n_chnls / groups;
    int c_start = g * C_per_group;
    int c_end = c_start + C_per_group;

    float* sum = smem;
    float* sum_sq = &smem[blockDim.x];

    int tid = threadIdx.x;
    sum[tid] = 0.f;
    sum_sq[tid] = 0.f;

    int elements = C_per_group * D * H * W;
    int elems_per_thread = (elements + blockDim.x - 1) / blockDim.x;
    int start = tid * elems_per_thread;
    int end = min(start + elems_per_thread, elements);

    for(int i=start; i<end; ++i) {
        int c = c_start + (i / (D*H*W)) % C_per_group;
        int d = (i / (H*W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = ((n * n_chnls + c) * D + d) * H * W + h * W + w;
        float val = input[idx];
        sum[tid] += val;
        sum_sq[tid] += val * val;
    }

    __syncthreads();

    for(int s=blockDim.x/2; s>0; s>>=1) {
        if(tid < s) {
            sum[tid] += sum[tid + s];
            sum_sq[tid] += sum_sq[tid + s];
        }
        __syncthreads();
    }

    float total_sum = sum[0];
    float total_sum_sq = sum_sq[0];
    float mean = total_sum / elements;
    float var = (total_sum_sq / elements) - (mean * mean);
    float inv_std = rsqrtf(var + epsilon);

    for(int i=start; i<end; ++i) {
        int c = c_start + (i / (D*H*W)) % C_per_group;
        int d = (i / (H*W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = ((n * n_chnls + c) * D + d) * H * W + h * W + w;
        float normalized = (input[idx] - mean) * inv_std;
        output[idx] = normalized * weight[c] + bias[c];
    }
}

torch::Tensor group_norm_rocm(torch::Tensor input, 
                             torch::Tensor weight,
                             torch::Tensor bias,
                             int groups,
                             float epsilon) {
    auto output = torch::empty_like(input);
    auto sizes = input.sizes();
    int n_batch = sizes[0];
    int n_chnls = sizes[1];
    int D = sizes[2], H = sizes[3], W = sizes[4];

    dim3 grid(n_batch, groups);
    dim3 block(256);
    size_t smem = 2 * block.x * sizeof(float);

    hipLaunchKernelGGL(group_norm_kernel, grid, block, smem, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        n_batch, n_chnls, D, H, W, groups, epsilon);

    return output;
}

#include <torch/extension.h>
