__global__ void clamp_div_kernel(const float* input, float* output, float min_value, float divisor, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        val = fmaxf(val, min_value);
        output[idx] = val / divisor;
    }
}

torch::Tensor clamp_div_rocm(torch::Tensor input, float min_value, float divisor) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(clamp_div_kernel, 
        dim3(grid_size), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        min_value, 
        divisor, 
        num_elements);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_activation_kernel(const float* input, float* output, int num_elements, float add_value, float scale) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];

        float softplus_val = log1pf(expf(x));
        float mish = x * tanhf(softplus_val);
        float after_add = mish + add_value;
        float clamped = fmaxf(-1.0f, fminf(after_add, 1.0f));
        output[idx] = clamped * scale;
    }
}

torch::Tensor fused_activation_rocm(torch::Tensor input, float add_value, float scale) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    auto stream = at::hip::getCurrentHIPStream();
    fused_activation_kernel<<<grid, block_size, 0, stream.stream()>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), num_elements, add_value, scale
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_softmax_sigmoid_kernel(const float* input, float* output, int C, int D, int H, int W) {
    int position = blockIdx.x;
    int batch = position / (D * H * W);
    int remainder = position % (D * H * W);
    int d = remainder / (H * W);
    remainder = remainder % (H * W);
    int h = remainder / W;
    int w = remainder % W;

    int c = threadIdx.x;
    if (c >= C) return;

    int input_idx = batch * C * D * H * W 
                    + c * D * H * W 
                    + d * H * W 
                    + h * W 
                    + w;
    float val = input[input_idx];

    extern __shared__ float shared_data[];
    float* s_max = shared_data;
    float* s_sum = shared_data + blockDim.x;

    s_max[c] = val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (c < stride) {
            s_max[c] = fmaxf(s_max[c], s_max[c + stride]);
        }
        __syncthreads();
    }
    float max_val = s_max[0];
    __syncthreads();

    float exp_val = expf(val - max_val);
    s_sum[c] = exp_val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (c < stride) {
            s_sum[c] += s_sum[c + stride];
        }
        __syncthreads();
    }
    float sum_exp = s_sum[0];
    __syncthreads();

    output[input_idx] = 1.0f / (1.0f + expf(-(exp_val / sum_exp)));
}

torch::Tensor fused_softmax_sigmoid_rocm(torch::Tensor x) {
    TORCH_CHECK(x.device().type() == torch::kCUDA, "Input tensor must be on CUDA device");
    auto sizes = x.sizes();
    int C = sizes[1];

    auto output = torch::empty_like(x);
    int batch_size = sizes[0];
    int D = sizes[2];
    int H = sizes[3];
    int W = sizes[4];

    int total_positions = batch_size * D * H * W;
    int block_size = C;
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    hipStream_t stream = at::hip::getCurrentHIPStream();
    fused_softmax_sigmoid_kernel<<<total_positions, block_size, shared_mem_size, stream>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        C,
        D,
        H,
        W
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_bias_div_swish_kernel(const float* input, const float* bias, float divide, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] + __ldg(bias);
        val /= divide;
        output[idx] = val * (1.0f / (1.0f + expf(-val)));
    }
}

torch::Tensor fused_bias_div_swish(torch::Tensor x, torch::Tensor bias, float divide) {
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bias_div_swish_kernel, 
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), bias.data_ptr<float>(), divide, out.data_ptr<float>(), size
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_gemm_scale_gelu_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float* output,
    float divisor,
    int batch_size,
    int input_size,
    int output_size
) {
    int output_col = blockIdx.x * blockDim.x + threadIdx.x;
    int batch_row = blockIdx.y * blockDim.y + threadIdx.y;

    if (batch_row >= batch_size || output_col >= output_size) return;

    float sum = 0.0f;
    for (int k = 0; k < input_size; ++k) {
        sum += x[batch_row * input_size + k] * weight[output_col * input_size + k];
    }
    sum += bias[output_col];
    sum /= divisor;

    // GELU approximation
    float gelu = 0.5f * sum * (1.0f + tanhf(0.7978845608f * (sum + 0.044715f * sum * sum * sum)));
    output[batch_row * output_size + output_col] = gelu;
}

torch::Tensor fused_gemm_scale_gelu_rocm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float divisor
) {
    int batch_size = x.size(0);
    int input_size = x.size(1);
    int output_size = weight.size(0);
    auto output = torch::zeros({batch_size, output_size}, x.options());

    dim3 block_size(32, 8);
    dim3 grid_size(
        (output_size + block_size.x - 1) / block_size.x,
        (batch_size + block_size.y - 1) / block_size.y
    );

    hipLaunchKernelGGL(
        fused_gemm_scale_gelu_kernel,
        grid_size,
        block_size,
        0,
        at::cuda::getCurrentHIPStream(),
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        divisor,
        batch_size,
        input_size,
        output_size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void mish_tanh_fused_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float softplus_val = log1pf(expf(x));
        float mish_val = x * tanhf(softplus_val);
        output[idx] = tanhf(mish_val);
    }
}

torch::Tensor mish_tanh_fused_rocm(torch::Tensor input) {
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous");
    auto output = torch::zeros_like(input);
    int size = input.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipStream_t stream = at::hip::getCurrentHIPStream();
    mish_tanh_fused_kernel<<<num_blocks, block_size, 0, stream>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void custom_gemm_kernel(const float* x, const float* weight, const float* bias, float* out, int batch_size, int in_features, int out_features) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < batch_size && col < out_features) {
        float sum = bias[col];
        for (int k = 0; k < in_features; ++k) {
            sum += x[row * in_features + k] * weight[col * in_features + k];
        }
        out[row * out_features + col] = sum;
    }
}

torch::Tensor custom_gemm_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = weight.size(0);
    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(16, 16);
    dim3 grid((out_features + block.x - 1) / block.x, (batch_size + block.y - 1) / block.y);

    hipLaunchKernelGGL(custom_gemm_kernel, grid, block, 0, 0, 
        x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        out.data_ptr<float>(), batch_size, in_features, out_features
    );
    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_divide_leaky_relu_kernel(const float* input, float divisor, float* output, int num_elements, float slope) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx] / divisor;
        output[idx] = fmaxf(val, val * slope);
    }
}

torch::Tensor fused_divide_leaky_relu_rocm(torch::Tensor input, float divisor, float slope) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_divide_leaky_relu_kernel,
        dim3(num_blocks), 
        dim3(block_size),
        0,
        at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        divisor,
        output.data_ptr<float>(),
        num_elements,
        slope
    );
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_act_add_kernel(const float* x_norm, const float* x_conv, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x_norm[idx];
        val = tanhf(val);
        float relu_val = fminf(fmaxf(val + 3, 0.0f), 6.0f);
        val = val * relu_val / 6.0f;
        output[idx] = x_conv[idx] + val;
    }
}

torch::Tensor fused_act_add_rocm(torch::Tensor x_norm, torch::Tensor x_conv) {
    auto size = x_norm.numel();
    TORCH_CHECK(size == x_conv.numel(), "Tensors must have the same size");
    auto output = torch::empty_like(x_conv);

    int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_act_add_kernel, dim3(num_blocks), dim3(block_size), 0, 0, 
        x_norm.contiguous().data_ptr<float>(), x_conv.contiguous().data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_subtract_tanh_subtract_kernel(const float* input, float sub1, float sub2, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] - sub1;
        val = tanhf(val);
        val = val - sub2;
        output[idx] = val;
    }
}

torch::Tensor fused_subtract_tanh_subtract_rocm(torch::Tensor input, float sub1, float sub2) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_subtract_tanh_subtract_kernel, 
        dim3(num_blocks), dim3(block_size), 0, 0, 
        input.data_ptr<float>(), sub1, sub2, output.data_ptr<float>(), size);

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_scale_bn_kernel(const float* x, const float* scale, const float* bn_weight, const float* bn_bias, float* running_mean, float* running_var, float* y, int batch_size, int out_features, float eps, float momentum, bool training) {
    int j = blockIdx.x;
    int tid = threadIdx.x;
    int stride = blockDim.x;

    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sum_sq = smem + blockDim.x;

    if (training) {
        float sum_local = 0.0f, sum_sq_local = 0.0f;

        for (int i = tid; i < batch_size; i += stride) {
            float val = x[i * out_features + j] * scale[j];
            sum_local += val;
            sum_sq_local += val * val;
        }

        s_sum[tid] = sum_local;
        s_sum_sq[tid] = sum_sq_local;
        __syncthreads();

        for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
            if (tid < offset) {
                s_sum[tid] += s_sum[tid + offset];
                s_sum_sq[tid] += s_sum_sq[tid + offset];
            }
            __syncthreads();
        }

        if (tid == 0) {
            float mean = s_sum[0] / batch_size;
            float var = (s_sum_sq[0] / batch_size) - (mean * mean);
            running_mean[j] = running_mean[j] * (1 - momentum) + mean * momentum;
            running_var[j] = running_var[j] * (1 - momentum) + var * momentum;
            s_sum[0] = mean;
            s_sum_sq[0] = var;
        }

        __syncthreads();
        float mean_val = s_sum[0], inv_std = 1.0f / sqrt(s_sum_sq[0] + eps);
        for (int i = tid; i < batch_size; i += stride) {
            float val = x[i * out_features + j] * scale[j];
            y[i * out_features + j] = (val - mean_val) * inv_std * bn_weight[j] + bn_bias[j];
        }
    } else {
        float mean_val = running_mean[j], inv_std = 1.0f / sqrt(running_var[j] + eps);
        for (int i = tid; i < batch_size; i += stride) {
            float val = x[i * out_features + j] * scale[j];
            y[i * out_features + j] = (val - mean_val) * inv_std * bn_weight[j] + bn_bias[j];
        }
    }
}

torch::Tensor fused_scale_bn(torch::Tensor x, torch::Tensor scale, torch::Tensor bn_weight, torch::Tensor bn_bias, torch::Tensor running_mean, torch::Tensor running_var, float eps, float momentum, bool training) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    int batch_size = x.size(0), out_features = x.size(1);
    auto y = torch::empty_like(x);
    int threads = 256;

    hipLaunchKernelGGL(fused_scale_bn_kernel, dim3(out_features), dim3(threads), 2*threads*sizeof(float), at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), scale.data_ptr<float>(), bn_weight.data_ptr<float>(), bn_bias.data_ptr<float>(), 
        running_mean.data_ptr<float>(), running_var.data_ptr<float>(), y.data_ptr<float>(), batch_size, out_features, eps, momentum, training);

    return y;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_lse_gelu_add_kernel(const float* input, const float* residual, float* output, int num_batches) {
    int batch_idx = blockIdx.x;

    float max_val = -INFINITY;
    float sum_exp = 0.0f;

    for(int i = 0; i < 1; ++i) {  // Input has size (B, 1)
        float val = input[batch_idx];
        if(val > max_val) max_val = val;
    }

    sum_exp = expf(input[batch_idx] - max_val);

    float lse = max_val + logf(sum_exp);

    // GELU approximation matching PyTorch's default
    float gelu = 0.5f * lse * (1.0f + erff(lse / 1.41421356237f));

    // Add residual (original_x is size (B, in_features))
    for(int feat = threadIdx.x; feat < %FEAT_SIZE%; feat += blockDim.x) {
        output[batch_idx * %FEAT_SIZE% + feat] = gelu + residual[batch_idx * %FEAT_SIZE% + feat];
    }
}

torch::Tensor fused_lse_gelu_add_rocm(torch::Tensor input, torch::Tensor residual) {
    int num_batches = input.size(0);
    auto output = torch::empty_like(residual);

    const int block_size = 256;
    fused_lse_gelu_add_kernel<<<num_batches, block_size>>>(
        input.data_ptr<float>(),
        residual.data_ptr<float>(),
        output.data_ptr<float>(),
        num_batches
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_kernel(const float* input, float* output, const float* weight, const float* bias,
                             int N, int C, int G, float eps, float slope, float scale) {
    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sqsum = s_sum + blockDim.x;

    int n = blockIdx.x;
    int g = blockIdx.y;
    int c_start = g * (C/G);
    int c_end = c_start + (C/G);
    int tid = threadIdx.x;

    float sum = 0.0f, sqsum = 0.0f;
    for (int c = c_start + tid; c < c_end; c += blockDim.x) {
        float val = input[n*C + c];
        sum += val;
        sqsum += val * val;
    }
    s_sum[tid] = sum;
    s_sqsum[tid] = sqsum;
    __syncthreads();

    for (int stride=blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid+stride];
            s_sqsum[tid] += s_sqsum[tid+stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = s_sum[0] / (C/G);
        float var = (s_sqsum[0]/(C/G) - mean*mean) + eps;
        float inv_std = rsqrtf(var);
        s_sum[0] = mean;
        s_sqsum[0] = inv_std * scale;
    }
    __syncthreads();

    float inv_std_scaled = s_sqsum[0];
    for (int c = c_start + tid; c < c_end; c += blockDim.x) {
        float x = input[n*C + c];
        float norm = (x - s_sum[0]) * inv_std_scaled * weight[c] + bias[c];
        output[n*C + c] = (norm > 0) ? norm : norm * slope;
    }
}

torch::Tensor fused_op(torch::Tensor x, torch::Tensor w, torch::Tensor b, 
                      int groups, float eps, float slope, float scale) {
    auto out = torch::empty_like(x);
    int N = x.size(0);
    int C = x.size(1);
    dim3 grid(N, groups);
    int block = 256;
    size_t smem = 2 * block * sizeof(float);
    fused_kernel<<<grid, block, smem>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), 
        w.data_ptr<float>(), b.data_ptr<float>(),
        N, C, groups, eps, slope, scale
    );
    return out;
}
